  plugin=(NeverLandTownySpecialization)Bukkit.getPluginManager().getPlugin("NeverLandTownySpecialization");specialization=(SpecializationService)Bukkit.getServicesManager().load(TownySpecializationApi.class);var productionMenu=field(Bukkit.getPluginCommand("townyspecialization").getExecutor(),"production");production=(ProductionService)field(productionMenu,"service");repository=production.repository();goods=Bukkit.getServicesManager().load(ProfileGoodsApi.class);api=Bukkit.getServicesManager().load(ServerMaterialsApi.class);materials=(ServerMaterials)field(field(Bukkit.getPluginManager().getPlugin("NeverLandTownyContracts"),"publicOrders"),"materials");
