  for(String shortName:List.of("Citizens","Builds","Contracts","Specialization","Seasons","Control"))check(Bukkit.getPluginManager().isPluginEnabled("NeverLandTowny"+shortName)&&!SuiteState.frozen("NeverLandTowny"+shortName),phase+": "+shortName+" enabled and unfrozen");
  mayor=actor(M,"SeasonFarmMayor");sponsor=actor(S,"SeasonPortMayor");applicant=actor(L,"SeasonResident");
