  workingBuildingsFixture();poll(()->goods.ready(),100,()->{catalog=production.catalog();check(specialization.canUseBuilding(T,"seed_vault"),"legacy specialization still authorizes its unique building");if(phase.equals("first")){check(markets.problem().isBlank(),"optional seasonal catalog and production provider ready");produce(mayor,FARM,T,"farm_provisions",()->produce(sponsor,PORT,U,"port_equipment",this::prepare));}else resume();});
