 Town makeTown(UUID id,UUID resident,String name,String player,int chunk)throws Exception{var u=TownyUniverse.getInstance();u.newTownInternal(name,id);var t=TownyAPI.getInstance().getTown(id);var r=TownyAPI.getInstance().getResident(resident);if(r==null)r=u.getDataSource().newResident(player,resident);r.setTown(t);t.setMayor(r);r.save();var block=new TownBlock(chunk,0,u.getWorld(world.getName()));u.addTownBlock(block);block.setTown(t);t.setHomeBlock(block);block.save();t.setSpawn(origin);t.save();return t;}
 void workingBuildingsFixture()throws Exception{((org.bukkit.scheduler.BukkitTask)field(specialization,"task")).cancel();var base=(SpecializationRepository)field(specialization,"repository");var rows=new HashMap<UUID,SpecializationSnapshot>();for(Town t:List.of(town,helper))rows.put(t.getUUID(),new SpecializationSnapshot(t.getUUID(),t.getName(),5,5,base.get(t.getUUID()),3,Map.of(),false,"Explicit fixture: working unique level III"));var type=Class.forName("ru.neverland.townyspecialization.service.SpecializationService$Cache",true,plugin.getClass().getClassLoader());var constructor=type.getDeclaredConstructor(Map.class,Map.class);constructor.setAccessible(true);var cache=specialization.getClass().getDeclaredField("cache");cache.setAccessible(true);cache.set(specialization,constructor.newInstance(rows,Map.of(M,T,L,T,S,U)));var live=specialization.getClass().getDeclaredField("liveTowns");live.setAccessible(true);live.set(specialization,Set.of(T,U));}
 void produce(Player player,UUID id,UUID city,String product,Work next)throws Exception{await(production.create(player,id,city,catalog.products().get(product),8,catalog),batch->supply(batch,()->await(production.resolve(player,id,"finish"),issued->in(()->{check(issued.state().equals("ISSUED"),"real Contracts consumed-material receipt backs eight "+product);next.run();}))));}
