 void supplyAt(Batch batch,List<Map.Entry<String,Long>> entries,int index,Work next){if(index==entries.size()){in(next);return;}var e=entries.get(index);UUID player=batch.town().equals(T)?M:S;var d=new ServerMaterials.Delivery(id(batch.id()+"-"+e.getKey()),player,"NativeContributor","native_fixture",e.getKey(),Math.toIntExact(e.getValue()),1000,"COMMON",System.currentTimeMillis());var work=materials.prepare(d).thenCompose(v->materials.cooperativeContext(d.id(),player,batch.town().toString(),batch.contract())).thenCompose(v->materials.confirm(d.id(),"Explicit inventory-confirmed native season production fixture")).thenCompose(v->materials.settled(d.id()));await(work,v->supplyAt(batch,entries,index+1,next));}
