 void prepare()throws Exception{
  denied(()->markets.preparation(applicant),"ordinary resident cannot prepare city reserves");menu.openStock(mayor,null,1);poll(()->windows.get(M).getItem(10)!=null,80,()->{check(lore(mayor,10).contains("Произведено городом")&&windows.get(M).getItem(10).getAmount()==1,"native stock menu uses safe icons and distinguishes real production");click(mayor,47);poll(()->windows.get(M).getItem(40)!=null,80,this::delayedReserve);});
 }
 void delayedReserve()throws Exception{
  check(lore(mayor,22).contains("Продовольственные партии")&&lore(mayor,22).contains("МСК"),"preview shows frozen quantities and explicit Moscow deadline before reserve");
  var locked=new CountDownLatch(1);release=new CountDownLatch(1);var worker=new Thread(()->{try(var c=DriverManager.getConnection("jdbc:sqlite:"+plugin.getDataFolder().toPath().resolve("production.sqlite"));var s=c.createStatement()){s.execute("BEGIN IMMEDIATE");locked.countDown();release.await(10,TimeUnit.SECONDS);s.execute("COMMIT");}catch(Throwable e){fail(e);}},"season-sql-delay-fixture");worker.setDaemon(true);worker.start();if(!locked.await(1,TimeUnit.SECONDS))throw new AssertionError("SQLite delay not acquired");click(mayor,40);later(3,()->{check(goods.active().isEmpty(),"real SQLite delay exposes no pending reserve through ACK cache");check(SuiteState.tryRun("native season SQL delay",()->{}),"Suite guard stays free while reserve disk ACK waits");click(mayor,40);release.countDown();poll(()->goods.active().size()==1,100,()->{prep=UUID.fromString((String)goods.active().getFirst().get("id"));await(goods.stock(T,1),rows->in(()->{check(number(rows,"farm_provisions","available")==7&&number(rows,"farm_provisions","reserved")==1,"double click reserves exact one party only after disk ACK");var before=seasons.productionMultiplier(T,"agrarian_complex");SuiteState.freeze(seasonsPlugin.getName());denied(()->markets.preparation(mayor),"module pause rejects new reserve without changing old seasonal coefficients");check(seasons.productionMultiplier(T,"agrarian_complex")==before&&goods.active().size()==1,"module pause keeps ACK reserve and old coefficients");SuiteState.thaw(seasonsPlugin.getName());await(markets.cancel(mayor,prep),cancelled->in(()->{check(cancelled.get("state").equals("CANCELLED"),"mayor neutrally releases own seasonal preparation");offer();}));}));});});
 }
 static long number(List<Map<String,Object>> rows,String product,String key){return rows.stream().filter(r->product.equals(r.get("product"))).mapToLong(r->((Number)r.get(key)).longValue()).findFirst().orElse(0);}
