   var changed=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(config.toFile());changed.set("exchanges.farm_port.give.farm_provisions",3);changed.save(config.toFile());markets.reload();poll(()->markets.catalog().exchanges().get("farm_port").give().get("farm_provisions")==3,80,()->{menu.openEntries(sponsor,null,1);poll(()->windows.get(S).getItem(10)!=null,80,()->{click(sponsor,10);poll(()->windows.get(S).getItem(40)!=null,80,()->{check(lore(sponsor,22).contains("× 2")&&!lore(sponsor,22).contains("× 3"),"second mayor sees stored offer after template changes");click(sponsor,40);poll(()->goods.active().isEmpty(),80,this::swapped);});});});
