 void boundary()throws Exception{await(markets.exchange(mayor,U,"farm_port"),quote->await(markets.confirm(mayor,quote),held->in(()->{UUID id=UUID.fromString((String)held.get("id"));seasons.override(world.getUID(),Season.SPRING);poll(()->goods.active().stream().noneMatch(row->id.toString().equals(row.get("id"))),160,()->{check(true,"provider observes one common calendar change and neutrally expires previous-season offer");await(goods.entry(id),expired->in(()->{check(expired.get("state").equals("EXPIRED"),"expired offer returns original reserved goods without exchange");await(markets.exchange(mayor,U,"farm_port"),last->await(markets.confirm(mayor,last),pendingRow->in(()->{pending=UUID.fromString((String)pendingRow.get("id"));Files.writeString(proof.resolve("expected.txt"),swap+"\n"+pending+"\n"+last.get("hash")+"\n");Files.copy(config,proof.resolve("season-markets-good.yml"));var bad=org.bukkit.configuration.file.YamlConfiguration.loadConfiguration(config.toFile());bad.set("enabled","BROKEN");bad.save(config.toFile());finishPhase();})));}));});})));}
