 void verifyAudit(){var job=new CompletableFuture<List<AuditRecord>>();Bukkit.getAsyncScheduler().runNow(this,t->{try{var rows=new ArrayList<AuditRecord>();AuditJournal.scan(plugin.getDataFolder().toPath().resolve("audit"),rows::add);job.complete(rows);}catch(Throwable e){job.completeExceptionally(e);}});await(job,rows->in(()->{var trade=rows.stream().filter(r->r.kind().equals("CITY_SEASON_FAIR")&&r.outcome().equals("SWAPPED")&&r.operation().equals(swap.toString())).toList();check(trade.size()==2&&trade.stream().map(r->r.from().id()).collect(java.util.stream.Collectors.toSet()).equals(Set.of(T.toString(),U.toString())),"admin journal has one durable direction per city for exact swap");check(rows.stream().anyMatch(r->r.kind().equals("CITY_SEASON_FAIR")&&r.outcome().equals("CANCELLED")&&r.actor().type().equals("CONSOLE")),"admin neutral cancellation records actual console actor");closing();}));}
